import { eventFacts, settlementFacts, activityRange, feedPage, eventPage } from './facts.js';
import { previousEvents } from './event-store.js';
import { compareLogs, ChainDataError } from './client.js';
import { registrationStart } from './positions.js';
import { playerAddress, uint } from './state.js';
import { isRun56Schema, jackpotBattleKey } from './schema.js';

// The Game's own award events, per deployment (chain/schema.js). Run 56: a coin draw's craps half
// logs CoinDrawCrapsWin, and the purchase-day fill draw is COIN_DRAW_BATTLE's CoinDrawBattleRun /
// CoinDrawBattlePot. Run 57+ (audit 0889affc1): CoinDrawCrapsWin is gone and there is no closed
// fill-draw field at all. The daily jackpot battle is an ordinary craps-table field at period 5
// (CRAPS: JackpotBattleLocked / JackpotBattleEntry for each awarded seat / JackpotBattleStarted,
// then CrapsBetSettled per seat); chain/craps.js replays it through the craps table like any window.
export const BATTLE_RUN = new Set(['CoinDrawBattleRun']);
export const BATTLE_POT = new Set(['CoinDrawBattlePot']);
export const jackpotEvents = () => ['JackpotEthWin', 'JackpotFlipWin', 'JackpotTicketWin', 'JackpotWhalePassWin',
  ...(isRun56Schema() ? ['CoinDrawCrapsWin'] : [])];
export const battleEvents = () => (isRun56Schema() ? ['CoinDrawBattleRun', 'CoinDrawBattlePot'] : []);
export const jackpotFactEvents = () => [...jackpotEvents(), ...battleEvents()];
export const jackpotSources = () => (isRun56Schema() ? ['GAME', jackpotBattleKey()] : ['GAME']);
const FLIP_WEI = 10n ** 18n;
// JackpotModule: a refused opener seat pays CRAPS_OPENER_SEAT_VALUE, a refused whole day
// (saturated pass bank) NORMAL_DAY_PASS_VALUE, both credited as FLIP in the draw's batch.
export const COIN_DRAW_OPENER_SEAT_FLIP = 2_400n * FLIP_WEI;
export const COIN_DRAW_DAY_PASS_FLIP = 22_800n * FLIP_WEI;
/** A fill-draw run that busted is an entrant, not a winner. */
export function isJackpotWinRow(row) {
  return !BATTLE_RUN.has(row.name) || BigInt(row.args.paid ?? 0) > 0n;
}
export function jackpotWin(row) {
  const a = row.args; const baf = Number(a.traitId) === 420;
  let awardType = ({ JackpotEthWin: baf ? 'eth_baf' : 'eth', JackpotFlipWin: 'flip', JackpotTicketWin: baf ? 'tickets_baf' : 'tickets',
    JackpotWhalePassWin: 'whale_pass', CoinDrawBattleRun: 'farFutureCoin', CoinDrawBattlePot: 'farFutureCoin', CoinDrawCrapsWin: 'craps_pass' })[row.name];
  // halfPasses: WhaleModule's copy of JackpotWhalePassWin (same topic0, audit 4254a877) names the count differently.
  let amount = a.amount ?? a.entryCount ?? a.halfPassCount ?? a.halfPasses ?? a.paid ?? a.pot;
  let crapsAward = null;
  if (row.name === 'CoinDrawCrapsWin') {
    const fullDay = a.fullDay === true || a.fullDay === 'true';
    const refused = a.refused === true || a.refused === 'true';
    crapsAward = fullDay ? 'day' : 'opener';
    // A seated award is one comp (a banked day pass, or tomorrow's opener seat); a refused one
    // was paid its FLIP value instead, so it is a FLIP win like any other.
    if (refused) { awardType = 'flip'; amount = fullDay ? COIN_DRAW_DAY_PASS_FLIP : COIN_DRAW_OPENER_SEAT_FLIP; } else amount = 1n;
  }
  const level = a.level ?? a.entryLevel ?? a.currentLevel ?? a.winnerLevel;
  return { ...row, winner: a.winner ?? a.player, level: level == null ? null : Number(level),
    traitId: a.traitId == null ? null : Number(a.traitId), amount: String(amount),
    ticketIndex: a.entryIndex == null ? null : Number(a.entryIndex), sourceLevel: a.sourceLevel == null ? null : Number(a.sourceLevel),
    winnerLevel: a.winnerLevel == null ? null : Number(a.winnerLevel), halfPassCount: a.halfPassCount ?? a.halfPasses ?? null,
    roundedUp: a.roundedUp ?? false, rebuyLevel: null, rebuyTickets: null, awardType, crapsAward,
    ...(BATTLE_POT.has(row.name) ? { coinDrawPot: true } : {}) };
}
export async function settlementWindow(s, day, signal) {
  const { fromBlock } = await activityRange(s, day, signal);
  const anchors = await eventFacts(s, ['DailyRngApplied', 'PrizePoolDailySnapshot'], { contract: 'GAME', fromBlock, signal });
  const start = anchors.find(row => row.name === 'DailyRngApplied' && Number(row.args.day) === day);
  const seal = anchors.find(row => row.name === 'PrizePoolDailySnapshot' && Number(row.args.day) === day);
  const next = start && anchors.find(row => row.name === 'DailyRngApplied' && compareLogs(row, start) > 0);
  const end = seal && (!next || compareLogs(seal, next) < 0) ? seal : next;
  return { start, seal, end, fromBlock: start?.blockNumber ?? fromBlock, toBlock: end?.blockNumber ?? s.block.number };
}
function grouped(rows, field) {
  const groups = new Map();
  for (const row of rows) {
    if (row.traitId == null || row.traitId > 255) continue;
    if (!groups.has(row.traitId)) groups.set(row.traitId, []);
    groups.get(row.traitId).push(row);
  }
  return [...groups].map(([traitId, wins]) => ({ traitId, winnerCount: wins.length, uniqueCount: new Set(wins.map(row => row.winner)).size,
    [field]: field === 'ticketsPerWinner' ? Number(wins.reduce((n, row) => n + BigInt(row.amount), 0n) / BigInt(wins.length))
      : String(wins.reduce((n, row) => n + BigInt(row.amount), 0n) / BigInt(wins.length)) })).sort((a, b) => a.traitId - b.traitId);
}
function prizeTotal(rows, numeric = false) {
  const total = rows.reduce((n, row) => n + BigInt(row.amount), 0n);
  return { winnerCount: rows.length, uniqueCount: new Set(rows.map(row => row.winner)).size, total: numeric ? Number(total) : String(total) };
}
/**
 * A day's DailyWinningTraits as the site reads its boards. Run 56 logs a bonus set and its target
 * level, and bonusTargetLevel 0 marks a purchase day with no bonus-trait coin draw (audit 5790a946).
 * Run 57+ (audit 9ee8986d) logs one board a day: the coin budget plays the jackpot battle on both
 * day kinds, so there is no bonus set and never a bonus-trait draw.
 */
export function dailyBoards(args) {
  if (!args) return { mainTraitsPacked: null, bonusTraitsPacked: null, bonusTargetLevel: null, bonusTraitDraw: null };
  const mainTraitsPacked = Number(args.mainTraitsPacked);
  if (!isRun56Schema()) return { mainTraitsPacked, bonusTraitsPacked: null, bonusTargetLevel: null, bonusTraitDraw: false };
  const bonusTargetLevel = Number(args.bonusTargetLevel);
  return { mainTraitsPacked, bonusTraitsPacked: Number(args.bonusTraitsPacked), bonusTargetLevel, bonusTraitDraw: bonusTargetLevel !== 0 };
}
/**
 * dailyFoilDraw[day] (DegenerusGameStorage._packFoilDraw): the main set at bits 0-31 and the cycle
 * level at 64-87 on both deployments. Run 56 also packs the bonus set at 32-63; audit 9ee8986d
 * leaves those bits zero. Null when the day never sealed a draw.
 */
export function decodeFoilDraw(packed) {
  const word = BigInt(packed ?? 0);
  if (word === 0n) return null;
  return { mainSet: Number(word & 0xffffffffn), bonusSet: isRun56Schema() ? Number((word >> 32n) & 0xffffffffn) : null,
    level: Number((word >> 64n) & 0xffffffn) };
}

/** Synthetic key for a day's fill-draw battle; never a CrapsBattle battleKey (those are bytes32). */
export const coinDrawBattleKey = day => `coin-draw:${Number(day)}`;

/**
 * A run-56 purchase day's fill-draw battle as the jackpot centre shows it: one closed battle
 * (COIN_DRAW_BATTLE) played in the draw's own call. Every run is listed, busts included, in
 * first-drawn order — a busted wallet was still drawn into the battle, which is what lets the
 * centre open it for them. Null from run 57 on (the jackpot battle is a craps-table field).
 */
export function coinDrawFillBattle(events, day) {
  const runs = events.filter(row => BATTLE_RUN.has(row.name));
  if (!runs.length) return null;
  const potRow = events.find(row => BATTLE_POT.has(row.name));
  const entrants = runs.map(row => ({ player: row.args.player, units: String(row.args.units), bankrollOut: String(row.args.bankrollOut),
    rolls: String(row.args.rolls), paid: String(row.args.paid), ...(row.args.chips != null ? { chips: Number(row.args.chips) } : {}) }));
  return { kind: 'fill-draw', key: coinDrawBattleKey(day), day, level: Number(runs[0].args.level), runs: runs.length,
    units: entrants.reduce((n, row) => n + Number(row.units), 0), paidRuns: entrants.filter(row => BigInt(row.paid) > 0n).length,
    totalPaid: String(entrants.reduce((n, row) => n + BigInt(row.paid), 0n)), pot: potRow ? String(potRow.args.pot) : '0',
    winner: potRow ? potRow.args.winner : null, transactionHash: runs[0].transactionHash, entrants };
}

export async function dailyJackpot(s, day, signal) {
  if (!s.jackpotDays) s.jackpotDays = new Map();
  if (s.jackpotDays.has(day)) return s.jackpotDays.get(day);
  const pending = composeDailyJackpot(s, day, signal); s.jackpotDays.set(day, pending);
  try { return await pending; } catch (error) { s.jackpotDays.delete(day); throw error; }
}
async function composeDailyJackpot(s, day, signal) {
  const window = await settlementWindow(s, day, signal);
  const [raw, drawRows, packed] = await Promise.all([
    eventFacts(s, [...jackpotFactEvents(), 'DecimatorResolved'], { contract: jackpotSources(), ...window, signal }),
    settlementFacts(s, 'GAME', ['DailyWinningTraits'], day, { signal }), s.field('GAME', 'dailyFoilDraw', day),
  ]);
  const events = window.start ? raw.filter(row => compareLogs(row, window.start) > 0 && (!window.end || compareLogs(row, window.end) < 0)) : [];
  const factEvents = jackpotFactEvents();
  const rows = events.filter(row => factEvents.includes(row.name) && isJackpotWinRow(row)).map(jackpotWin);
  const draw = drawRows.at(-1)?.args;
  const foilDraw = decodeFoilDraw(packed);
  const level = foilDraw ? foilDraw.level : rows.find(row => row.awardType === 'eth')?.level ?? null;
  const purchaseLevel = level;
  // Run 57+ has no roll-2 board: the day-1 early-bird tickets (sourceLevel level + 1) are drawn on
  // the day's one main board, so they reveal with roll 1. Roll 2 keeps the trait-less battle FLIP.
  const oneBoard = !isRun56Schema();
  const nearTickets = row => row.awardType === 'tickets' && row.sourceLevel !== purchaseLevel;
  const roll1Rows = rows.filter(row => ['eth', 'whale_pass'].includes(row.awardType) || row.awardType === 'tickets' && (row.sourceLevel === purchaseLevel || oneBoard));
  const roll2Rows = rows.filter(row => ['flip', 'farFutureCoin', 'craps_pass'].includes(row.awardType) || nearTickets(row) && !oneBoard);
  const winView = row => ({ ...row, quadrant: row.traitId == null || row.traitId > 255 ? -1 : row.traitId >> 6 });
  const eth = rows.filter(row => row.awardType === 'eth'); const tickets = roll1Rows.filter(row => row.awardType === 'tickets' && !nearTickets(row));
  const near = rows.filter(row => row.awardType === 'flip'); const far = rows.filter(row => row.awardType === 'farFutureCoin');
  const whale = rows.find(row => row.awardType === 'whale_pass' && Number(row.args.source) === 1);
  const soloRow = whale && eth.find(row => row.winner === whale.winner && row.transactionHash === whale.transactionHash);
  const solo = soloRow ? { traitId: soloRow.traitId, winner: soloRow.winner, ethAmount: soloRow.amount, hasWhalePass: true } : null;
  // JackpotModule (audit 5790a946): a run-56 purchase day emits DailyWinningTraits with
  // bonusTargetLevel 0 because it has NO bonus-trait coin draw — its coin leg is the fill draw's
  // craps battle. The bonus set it still packs feeds only that day's foil claims, so decoding it
  // into four bonus badges would render a phantom draw with zero winners. Level 1's opening day
  // passes 1. From run 57 no day has a bonus draw (see dailyBoards).
  const { mainTraitsPacked, bonusTraitsPacked: bonusPacked, bonusTargetLevel, bonusTraitDraw } = dailyBoards(draw);
  const nearGroups = grouped(near, 'coinPerWinner');
  const fillBattle = coinDrawFillBattle(events, day);
  // Bucket composition is intentionally lazy: reconstructing every losing
  // player's entries is not necessary to show the authoritative payout.
  const bonusDraw = bonusPacked == null || bonusTraitDraw === false ? [] : [24, 16, 8, 0].map(shift => {
    const traitId = (bonusPacked >>> shift) & 255; const group = nearGroups.find(row => row.traitId === traitId);
    return { traitId, bucketTickets: null, bucketHolders: null, winnerCount: group?.winnerCount ?? 0, uniqueCount: group?.uniqueCount ?? 0, coinPerWinner: group?.coinPerWinner ?? '0' };
  });
  const bafEth = rows.filter(row => row.awardType === 'eth_baf'), bafTickets = rows.filter(row => row.awardType === 'tickets_baf');
  const dec = events.find(row => row.name === 'DecimatorResolved');
  const summary = { day, blockRange: { start: String(window.fromBlock), end: window.seal ? String(window.toBlock) : null },
    rollOne: { mainTraitsPacked, eth: grouped(eth.filter(row => row !== soloRow), 'ethPerWinner'), tickets: grouped(tickets, 'ticketsPerWinner'), solo },
    rollTwo: { bonusTraitsPacked: bonusPacked, bonusTargetLevel, bonusTraitDraw, bonusDraw, coin: nearGroups,
      farFuture: { resolved: Boolean(window.seal), winnerCount: far.length, totalCoin: String(far.reduce((sum, row) => sum + BigInt(row.amount), 0n)) },
      coinDrawBattle: fillBattle },
    baf: bafEth.length || bafTickets.length ? { triggered: true, level, eth: prizeTotal(bafEth), tickets: prizeTotal(bafTickets, true) } : null,
    decimator: dec ? { triggered: true, level: Number(dec.args.lvl), poolEth: dec.args.poolWei, totalBurn: dec.args.totalBurn } : null };
  const byWinner = new Map();
  for (const row of rows) {
    if (!byWinner.has(row.winner)) byWinner.set(row.winner, { address: row.winner, totalEth: 0n, ticketCount: 0, coinTotal: 0n, hasBonus: false, hasBaf: false,
      winningLevel: row.level ?? level, traitBurnEntries: null, bafPrize: { eth: 0n, tickets: 0 }, decimatorPrize: { regularEth: '0', lootboxEth: '0' }, breakdown: [] });
    const winner = byWinner.get(row.winner);
    if (row.awardType.startsWith('eth')) winner.totalEth += BigInt(row.amount);
    if (row.awardType.startsWith('tickets')) winner.ticketCount += Number(row.amount);
    if (['flip', 'farFutureCoin'].includes(row.awardType)) winner.coinTotal += BigInt(row.amount);
    if (row.awardType === 'eth_baf') winner.bafPrize.eth += BigInt(row.amount);
    if (row.awardType === 'tickets_baf') winner.bafPrize.tickets += Number(row.amount);
    winner.hasBonus ||= roll2Rows.includes(row); winner.hasBaf ||= row.awardType.endsWith('_baf'); winner.breakdown.push(winView(row));
  }
  const winners = [...byWinner.values()].sort((a, b) => a.totalEth > b.totalEth ? -1 : a.totalEth < b.totalEth ? 1 : b.ticketCount - a.ticketCount);
  return { day, level, summary, winners, roll1: { day, level, purchaseLevel, wins: roll1Rows.map(winView) },
    roll2: { day, level, purchaseLevel, wins: roll2Rows.map(winView), bonusTraitDraw, coinDrawBattle: fillBattle },
    status: !window.seal ? 'processing' : rows.length ? 'resolved' : 'resolved-no-winners' };
}

export async function readJackpotRoute(s, url, { signal } = {}) {
  const p = url.pathname.split('/').filter(Boolean); const q = url.searchParams;
  if (p[0] === 'game' && p[1] === 'jackpot' && ['latest-day', 'earliest-day', 'last-day'].includes(p[2])) {
    if (p[2] === 'earliest-day') {
      const draws = await eventFacts(s, ['DailyWinningTraits'], { contract: 'GAME', signal });
      return { earliestDay: draws.length ? Number(draws[0].args.day) : null };
    }
    const seals = await previousEvents(s.client, 'GAME', 'PrizePoolDailySnapshot', { blockNumber: s.block.number, logIndex: Number.MAX_SAFE_INTEGER }, { signal });
    const sealed = Number(seals.at(-1)?.args.day ?? 0);
    const rows = await previousEvents(s.client, 'GAME', 'DailyWinningTraits', { blockNumber: s.block.number, transactionIndex: Number.MAX_SAFE_INTEGER, logIndex: Number.MAX_SAFE_INTEGER },
      { signal, accept: row => Number(row.args.day) <= sealed });
    const day = rows.length ? Number(rows.at(-1).args.day) : null;
    if (p[2] === 'latest-day') return { latestDay: day };
    return day == null ? { day: null, status: 'pre-game' } : dailyJackpot(s, day, signal);
  }
  if (p[0] === 'game' && p[1] === 'jackpot' && p[2] === 'day') {
    const data = await dailyJackpot(s, uint(p[3]), signal);
    if (p[4] === 'summary') return data.summary;
    if (p[4] === 'winners') return { day: data.day, level: data.level, winners: data.winners };
    if (p[4] === 'roll1' || p[4] === 'roll2') return data[p[4]];
  }
  if (p[0] === 'player' && p[2] === 'jackpot-history') {
    const page = await eventPage(s, jackpotFactEvents(), url, { contract: jackpotSources(), player: playerAddress(p[1]), signal });
    return { wins: page.rows.filter(isJackpotWinRow).map(jackpotWin), nextCursor: page.nextCursor };
  }
  if (p[0] === 'game' && p[1] === 'jackpot' && /^\d+$/.test(p[2])) return levelJackpot(s, uint(p[2]), p[3], p[4], q, signal);
  if (p[0] === 'game' && p[1] === 'baf' && p[3] === 'resolution') return bafResolution(s, uint(p[2]), signal);
  return undefined;
}

export function overviewRows(rows) {
  const groups = new Map();
  for (const row of rows) {
    if (row.traitId === 420 || row.awardType === 'whale_pass') continue;
    const key = row.traitId == null ? 'bonus' : row.traitId;
    if (!groups.has(key)) groups.set(key, []); groups.get(key).push(row);
  }
  return [...groups.values()].map(group => {
    const traitId = group[0].traitId; const eth = group.filter(r => r.awardType === 'eth');
    const ticket = group.filter(r => r.awardType === 'tickets'); const coin = group.filter(r => ['flip','farFutureCoin'].includes(r.awardType));
    const average = list => list.length ? list.reduce((sum,r) => sum + BigInt(r.amount), 0n) / BigInt(list.length) : 0n;
    return { type: traitId == null ? 'bonus' : 'symbol', traitId, quadrant: traitId == null ? -1 : traitId >> 6,
      winnerCount: Math.max(eth.length, ticket.length, coin.length), uniqueWinnerCount: new Set(group.map(r=>r.winner)).size,
      coinPerWinner: String(average(coin)), ticketsPerWinner: Number(average(ticket)), ethPerWinner: String(average(eth)),
      spreadBuckets: payoutSpread(eth), ticketSubRow: ticket.length ? { wins: ticket.length, amountPerWin: String(average(ticket)) } : null };
  }).sort((a,b)=>(a.quadrant < 0 ? 5 : a.quadrant) - (b.quadrant < 0 ? 5 : b.quadrant) || a.traitId-b.traitId);
}
async function levelJackpot(s, level, route, rawPlayer, q, signal) {
  const player = route === 'player' ? playerAddress(rawPlayer) : null;
  const day = q.has('day') ? uint(q.get('day')) : null;
  let rows, daily;
  if (day != null) {
    daily = await dailyJackpot(s, day, signal);
    rows = daily.winners.flatMap(winner => winner.breakdown);
  } else {
    rows = (await eventFacts(s, jackpotFactEvents(), { contract: jackpotSources(), ...(player ? { player } : {}), fromBlock: await registrationStart(s, level), signal }))
      .filter(isJackpotWinRow).map(jackpotWin)
      .filter(row => row.level === level || row.sourceLevel === level);
  }
  if (!route) return { level, distributions: rows.map(row => ({ ...row, day })) };
  if (route === 'player') {
    const mine = rows.filter(row => row.winner === player);
    const main = daily ? daily.roll1.wins.filter(row => row.winner === player) : mine.filter(row => row.awardType === 'eth' || row.awardType === 'tickets' && row.sourceLevel === level);
    const future = daily ? daily.roll2.wins.filter(row => row.winner === player && row.awardType !== 'farFutureCoin') : mine.filter(row => row.awardType === 'flip');
    const far = mine.filter(row => row.awardType === 'farFutureCoin');
    return { level, player, roll1Rows: overviewRows(main), roll2: { future: overviewRows(future), farFuture: overviewRows(far) }, hasBonus: future.length + far.length > 0,
      mainTraitsPacked: daily?.summary.rollOne.mainTraitsPacked ?? null, bonusTraitsPacked: daily?.summary.rollTwo.bonusTraitsPacked ?? null };
  }
  if (route === 'overview') {
    const bafEth = rows.filter(row => row.awardType === 'eth_baf'); const bafTicket = rows.filter(row => row.awardType === 'tickets_baf');
    return { level, day, farFutureResolved: rows.some(row=>row.awardType==='farFutureCoin'), rows: overviewRows(rows),
      baf: { triggered: bafEth.length + bafTicket.length > 0, eth: prizeTotal(bafEth), tickets: prizeTotal(bafTicket,true) } };
  }
  return undefined;
}
async function bafResolution(s, level, signal) {
  const fromBlock = await registrationStart(s, level);
  const [prizes, skipped] = await Promise.all([
    eventFacts(s, ['JackpotEthWin','JackpotTicketWin'], { contract: 'GAME', filters: { level, entryLevel: level, traitId: 420 }, fromBlock, signal }),
    eventFacts(s, ['BafSkipped'], { contract: 'JACKPOTS', filters: { lvl: level }, fromBlock, signal }),
  ]);
  const eth = prizes.filter(row=>row.name==='JackpotEthWin').map(jackpotWin), tickets = prizes.filter(row=>row.name==='JackpotTicketWin').map(jackpotWin);
  const anchor = skipped[0] ?? prizes[0];
  const rng = anchor ? (await previousEvents(s.client, 'GAME','DailyRngApplied',anchor,{signal})).at(-1) : null;
  return { level, status: skipped.length ? 'skipped' : prizes.length ? 'closed' : 'open', day: skipped.length ? Number(skipped[0].args.day) : rng ? Number(rng.args.day) : null,
    rngWord: rng ? String(rng.args.finalWord) : null, estimatedPoolWei: eth[0] ? String(BigInt(eth[0].amount)*20n) : null,
    awards: { ethCount: eth.length, ethUnique: new Set(eth.map(r=>r.winner)).size, ethTotal: prizeTotal(eth).total,
      ticketCount: tickets.length, ticketUnique: new Set(tickets.map(r=>r.winner)).size, ticketEntries: String(prizeTotal(tickets).total) } };
}

function payoutSpread(rows) {
  const perPlayer = new Map();
  for (const row of rows) perPlayer.set(row.winner,(perPlayer.get(row.winner)??0n)+BigInt(row.amount));
  const values=[...perPlayer.values()].sort((a,b)=>a<b?-1:a>b?1:0);
  if(values.length<2)return [false,true,false];
  const low=values[0],high=values.at(-1);if(low===high)return [true,true,true];
  const offset=values[Math.floor(values.length/2)]-low,third=(high-low)/3n;
  return offset<=third?[true,false,false]:offset<=third*2n?[false,true,false]:[false,false,true];
}
